      employee: { id: empId },
      division: { id: divisionId },
      startDate: `${YEAR}-${String(MONTH).padStart(2, "0")}-01`,
      isMainEmployer: true,
      taxDeductionCode: "loennFraHovedarbeidsgiver",
    });
